window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7392d3f39f29c9f9"]={"versions": [{"id": "FIG-7392d3f39f29c9f9", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilschritts innerhalb der AUTOSAR E2E-Bibliothek (End-to-End-Kommunikationsabsicherung). Das Diagramm modelliert den internen Ablauf des Einzelschritts „Read Counter“ der Prüffunktion <code>E2E_P06Check()</code> für das E2E-Profil 6 (Classic und Adaptive Platform).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Kontext-Element ist die Funktion bzw. Aktivität <code>E2E_P06Check()</code>. Das Diagramm enthält einen Startknoten (Initial Node), eine zentrale Aktionsstufe (Action Node) und einen Endknoten (Activity Final Node). Schnittstellen und Entitäten sind:</p>\n<ul class=\"fig-list\"><li>Eingangs-Datenarray: <code>Data[]</code>\n</li><li>Konfigurationsparameter / Byte-Offset: <code>Offset</code>\n</li><li>Zielvariable: lokale Variable <code>ReceivedCounter</code> vom Typ <code>uint8</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Sequenz verläuft linear und deterministisch:</p>\n<ol class=\"fig-list\"><li>Start am Initial Node nach Eintritt in den Teilschritt „Read Counter“.\n</li><li>Ausführung der Aktion: Das Datenbyte an der Position <code>Data[Offset+4]</code> wird in Big-Endian-Bytereihenfolge ausgelesen und in die lokale Variable <code>ReceivedCounter</code> (Typ <code>uint8</code>) kopiert.\n</li><li>Übergang zum Activity Final Node und Abschluss des Leseschritts.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend gemäß Anforderung <code>[PRS_E2E_00433]</code> (bzw. Trace zu <code>RS_E2E_08539</code>). Bei der Implementierung von Profil 6 Check ist der Sequenzzähler zwingend an Byte-Position <code>Offset + 4</code> als Einzelbyte (<code>uint8</code>) zu extrahieren. Obwohl bei einem Einzelbyte die Bytereihenfolge keinen Einfluss auf die Bitwertigkeit innerhalb des Bytes hat, legt die Spezifikation explizit „Big Endian order“ für das Profil fest.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cc06c6a0d162c53a", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilschritts innerhalb der AUTOSAR E2E-Bibliothek (End-to-End-Kommunikationsabsicherung). Das Diagramm modelliert den internen Ablauf des Einzelschritts „Read Counter“ der Prüffunktion <code>E2E_P06Check()</code> für das E2E-Profil 6 (Classic und Adaptive Platform).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Kontext-Element ist die Funktion bzw. Aktivität <code>E2E_P06Check()</code>. Das Diagramm enthält einen Startknoten (Initial Node), eine zentrale Aktionsstufe (Action Node) und einen Endknoten (Activity Final Node). Schnittstellen und Entitäten sind:</p>\n<ul class=\"fig-list\"><li>Eingangs-Datenarray: <code>Data[]</code>\n</li><li>Konfigurationsparameter / Byte-Offset: <code>Offset</code>\n</li><li>Zielvariable: lokale Variable <code>ReceivedCounter</code> vom Typ <code>uint8</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Sequenz verläuft linear und deterministisch:</p>\n<ol class=\"fig-list\"><li>Start am Initial Node nach Eintritt in den Teilschritt „Read Counter“.\n</li><li>Ausführung der Aktion: Das Datenbyte an der Position <code>Data[Offset+4]</code> wird in Big-Endian-Bytereihenfolge ausgelesen und in die lokale Variable <code>ReceivedCounter</code> (Typ <code>uint8</code>) kopiert.\n</li><li>Übergang zum Activity Final Node und Abschluss des Leseschritts.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend gemäß Anforderung <code>[PRS_E2E_00433]</code> (bzw. Trace zu <code>RS_E2E_08539</code>). Bei der Implementierung von Profil 6 Check ist der Sequenzzähler zwingend an Byte-Position <code>Offset + 4</code> als Einzelbyte (<code>uint8</code>) zu extrahieren. Obwohl bei einem Einzelbyte die Bytereihenfolge keinen Einfluss auf die Bitwertigkeit innerhalb des Bytes hat, legt die Spezifikation explizit „Big Endian order“ für das Profil fest.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-7392d3f39f29c9f9", "to": "FIG-cc06c6a0d162c53a", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
